"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Clock } from "@/components/ui/icons";

// Timeline Item: generated by UIX from the design system. Same variants and sizes as the Figma component.

const timelineItemVariants = cva(
  "skin-quiet flex gap-3",
  {
    variants: {
      status: {
        done: "[&_[data-slot=dot]]:bg-brand [&_[data-slot=line]]:bg-brand [&_[data-slot=title]]:text-fg-primary",
        current: "[&_[data-slot=dot]]:bg-brand [&_[data-slot=dot]]:ring-4 [&_[data-slot=dot]]:ring-brand-subtle [&_[data-slot=line]]:bg-line-default [&_[data-slot=title]]:text-fg-primary",
        upcoming: "[&_[data-slot=dot]]:bg-surface [&_[data-slot=dot]]:border-2 [&_[data-slot=dot]]:border-line-strong [&_[data-slot=line]]:bg-line-default [&_[data-slot=title]]:text-fg-secondary",
      },
    },
    defaultVariants: {
      status: "done",
    },
  },
);

export interface TimelineItemProps
  extends Omit<React.LiHTMLAttributes<HTMLLIElement>, "title">,
    VariantProps<typeof timelineItemVariants> {
  title: React.ReactNode;
  description?: React.ReactNode;
  time?: React.ReactNode;
  /** Hides the line below the dot (set it on the final item). */
  last?: boolean;
}

const TimelineItem = React.forwardRef<HTMLLIElement, TimelineItemProps>(
  ({ className, status, title, description, time, last = false, ...props }, ref) => (
    <li data-slot="timeline" data-kind="surface" ref={ref} className={cn(timelineItemVariants({ status }), className)} {...props}>
      <div className="flex flex-col items-center self-stretch gap-1">
        <span data-slot="dot" className="mt-1 shrink-0 rounded-full size-3" />
        {last ? null : <span data-slot="line" className="w-0.5 flex-1 min-h-[44px]" />}
      </div>
      <div className="flex min-w-0 flex-1 flex-col gap-0-5 pb-4">
        <p data-slot="title" className="text-label-large">{title}</p>
        {description ? <p className="text-body-small text-fg-secondary">{description}</p> : null}
        {time ? <p className="flex items-center gap-1 text-body-xs text-fg-tertiary [&_svg]:size-3 [&_svg]:text-icon-secondary"><Clock aria-hidden />{time}</p> : null}
      </div>
    </li>
  ),
);
TimelineItem.displayName = "TimelineItem";

const Timeline = React.forwardRef<HTMLOListElement, React.HTMLAttributes<HTMLOListElement>>(({ className, ...props }, ref) => (
  <ol ref={ref} className={cn("flex flex-col", className)} {...props} />
));
Timeline.displayName = "Timeline";

export { Timeline, TimelineItem, timelineItemVariants };
